  const n = typeof v === 'number' ? v : parseFloat(v);
  if (!Number.isFinite(n)) return { text: '—', clr: '#64748b' };
  const pct = Math.abs(n) <= 1.5 ? n * 100 : n;
  const sign = pct > 0 ? '+' : '';
  return {
    text: `${sign}${pct.toFixed(2)}%`,
    clr: pct > 0 ? '#22c55e' : pct < 0 ? '#ef4444' : '#64748b',
  };
}

